package neural

import "core:fmt"
import "core:math"
import "core:mem"
import "core:os"

d_model: int :: 18432
num_layers: int :: 384

NeuralState :: struct {
    potential: f64,
    quantum_phase: f64,
    lorenz_params: [3]f64,
    profile: string,
    spline_coeffs: [][5]f64,
}

update_state :: proc(state: ^NeuralState, token_embedding: []f64, grid: int) {
    sum_emb: f64 = 0.0
    for emb in token_embedding {
        sum_emb += emb
    }
    g: int = grid
    if g <= 0 {
        g = 1
    }
    scale: f64 = 0.01
    dm: f64 = f64(d_model)
    lgarg: f64 = dm * f64(g)
    if lgarg <= 1.0 {
        lgarg = 1.0000000000000002
    }
    state.potential += sum_emb * scale * math.log_f64(lgarg)
    state.quantum_phase += math.PI / 180.0
    state.profile = "Updated"
}

make_uniform_knots :: proc(min_x: f64, max_x: f64, grid: int, degree: int) -> []f64 {
    g := grid
    if g < 2 {
        g = 2
    }
    k := degree
    if k < 0 {
        k = 0
    }
    n_intervals := g - 1
    n_basis := n_intervals + k
    n_knots := n_basis + k + 1
    knots := mem.make_slice[f64](n_knots)
    if max_x <= min_x {
        max_x = min_x + 1.0
    }
    for i in 0 .. k {
        knots[i] = min_x
    }
    for i in 0 .. n_intervals {
        t := min_x + (max_x - min_x) * f64(i) / f64(n_intervals)
        knots[k + i] = t
    }
    for i in 0 .. k {
        knots[k + n_intervals + i] = max_x
    }
    return knots
}

b_spline_basis :: proc(x: f64, knots: []f64, degree: int) -> []f64 {
    n_knots := len(knots)
    if degree < 0 {
        return mem.make_slice[f64](0)
    }
    k := degree
    n_basis := n_knots - k - 1
    if n_basis <= 0 {
        return mem.make_slice[f64](0)
    }
    if k == 0 {
        basis0 := mem.make_slice[f64](n_basis)
        for i in 0 .. n_basis {
            a := knots[i]
            b := knots[i + 1]
            val: f64 = 0.0
            if a < b {
                if x >= a && x < b {
                    val = 1.0
                } else if x == b && i + 1 == n_basis {
                    val = 1.0
                }
            }
            basis0[i] = val
        }
        return basis0
    }
    prev := b_spline_basis(x, knots, k - 1)
    basis := mem.make_slice[f64](n_basis)
    for i in 0 .. n_basis {
        left_num := x - knots[i]
        left_den := knots[i + k] - knots[i]
        left_term: f64 = 0.0
        if left_den != 0.0 && i < len(prev) {
            left_term = (left_num / left_den) * prev[i]
        }
        right_num := knots[i + k + 1] - x
        right_den := knots[i + k + 1] - knots[i + 1]
        right_term: f64 = 0.0
        if right_den != 0.0 && i + 1 < len(prev) {
            right_term = (right_num / right_den) * prev[i + 1]
        }
        basis[i] = left_term + right_term
    }
    return basis
}

kan_spline_eval :: proc(x: f64, coeffs: []f64, grid: int) -> f64 {
    degree := 3
    knots := make_uniform_knots(-1.0, 1.0, grid, degree)
    defer mem.free_slice(knots)
    basis := b_spline_basis(x, knots, degree)
    defer mem.free_slice(basis)
    n_basis := len(basis)
    if n_basis == 0 {
        return 0.0
    }
    c := coeffs
    if len(c) < n_basis {
        tmp := mem.make_slice[f64](n_basis)
        for i in 0 .. n_basis {
            if i < len(c) {
                tmp[i] = c[i]
            } else {
                tmp[i] = 0.0
            }
        }
        c = tmp
        defer mem.free_slice(tmp)
    }
    y: f64 = 0.0
    for i in 0 .. n_basis {
        y += c[i] * basis[i]
    }
    if math.isnan_f64(y) || math.is_inf_f64(y) {
        return 0.0
    }
    return y
}

main :: proc() {
    state := NeuralState{
        potential = 0.0,
        quantum_phase = 0.0,
        lorenz_params = [3]f64{10.0, 28.0, 8.0/3.0},
        profile = "",
        spline_coeffs = mem.make_slice[[5]f64](0),
    }
    defer {
        mem.free_slice(state.spline_coeffs)
    }
    token_embedding := []f64{1.0, 0.5, -0.25, 2.0, 3.5}
    update_state(&state, token_embedding, 16)
    coeffs := []f64{0.2, -0.1, 0.3, 0.5, -0.4, 0.1, 0.0, 0.2}
    y0 := kan_spline_eval(-0.75, coeffs, 16)
    y1 := kan_spline_eval(0.0, coeffs, 16)
    y2 := kan_spline_eval(0.9, coeffs, 16)
    _, _ = fmt.println("potential=", state.potential, " phase=", state.quantum_phase, " profile=", state.profile)
    _, _ = fmt.println("spline(-0.75)=", y0, " spline(0.0)=", y1, " spline(0.9)=", y2)
    _, _ = os.exit(0)
}
